function moneyInput(input){const raw=input.value.trim().replace(',','.');if(!/^\d+(\.\d{1,2})?$/.test(raw))throw new Error('Vul een bedrag in euro’s in, bijvoorbeeld 34,45.');return Math.round(Number(raw)*100);}
